    },
    {
      "claim": "Une initiative est invalide si elle viole l'unité de la forme, l'unité de la matière ou le droit international impératif.",
      "verdict": "supported"
    },
    {
      "claim": "Le délai pour déposer une initiative populaire est de 18 mois à compter de son lancement.",
      "verdict": "unverifiable"
    },
    {
      "claim": "Le nombre de signatures requises pour soumettre une initiative populaire au vote est de 100 000 signatures valables de citoyens suisses dans un délai de 18 mois.",
      "verdict": "unverifiable"
